    private static async Task Add(AppDbContext db, string language, int suffix, string title, string description, string subject, string introduction, SlideDraft[] slides, string summary, QuizItem[] quiz, TaskItem[] tasks)
    {
        var id = Guid.Parse($"00000000-0000-0000-0000-00000000000{suffix}");
        if (await db.Lectures.AnyAsync(l => l.Id == id)) return;
        db.Lectures.Add(new Lecture { Id = id, Language = language, Title = title, Description = description, Subject = subject, Introduction = introduction, Summary = summary, Level = "Начальный", IsDemo = true, IsPublished = true, SourceName = language == "kk" ? "Үлгі дәріс" : "Demo lecture", ExercisesJson = JsonSerializer.Serialize(new { quiz, tasks }, new JsonSerializerOptions(JsonSerializerDefaults.Web)), Slides = slides.Select((s,i) => new Slide { Id = Guid.NewGuid(), OrderIndex = i, NarrationText = s.Narration, ContentJson = JsonSerializer.Serialize(new { title = s.Title, bullets = s.Bullets }) }).ToList() });
        await db.SaveChangesAsync();
    }
